// ─── File: src/main/java/com/bank/vo/model/Money.java ───
package com.bank.vo.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.util.Objects;

@Embeddable   // value object: amount + currency always travel together
public class Money {
    @Column(name = "balance_amount")
    private BigDecimal amount;
    @Column(name = "balance_currency")
    private String currency;

    protected Money() { }
    public Money(BigDecimal amount, String currency) {
        this.amount = Objects.requireNonNull(amount);
        this.currency = Objects.requireNonNull(currency);
    }
    public Money add(Money other) {
        if (!currency.equals(other.currency)) throw new IllegalArgumentException("currency mismatch");
        return new Money(amount.add(other.amount), currency);
    }
    @Override public boolean equals(Object o) {
        if (!(o instanceof Money m)) return false;
        return amount.compareTo(m.amount) == 0 && currency.equals(m.currency);
    }
    @Override public int hashCode() { return Objects.hash(amount.stripTrailingZeros(), currency); }
    public BigDecimal getAmount() { return amount; }
}
